Translate("zhCN", "kingdom-of-stormwind", {
	title = "暴风王国",
	sections = {
		{
			title = "概述",
			text = [=[暴风王国是{link:eastern-kingdoms}东部王国{/link}中仍然屹立的最强大的{link:humans}人类{/link}国度。它的中心是白色的{link:stormwind-city}暴风城{/link}，周围环绕着{link:elwynn-forest}艾尔文{/link}的森林、{link:westfall}西部荒野{/link}的田野、{link:redridge-mountains}赤脊山{/link}的丘陵和{link:duskwood}暮色森林{/link}的幽暗{link:moonglade}林地{/link}。它两度被毁，又两度重建，如今领导着{link:alliance}联盟{/link}。然而它的王座空悬，军队远离故土，边境上敌人遍布。]=],
		},
		{
			title = "起源",
			text = [=[当{link:arathor}阿拉索{/link}帝国开始分崩离析时，{link:arathi-highlands}阿拉希{/link}血脉的最后继承人离开了旧都激流城，向南迁徙。他们在一片青翠而隐蔽的土地上建立了一个新王国，并将其命名为{link:azeroth}艾泽拉斯{/link}，首都为{link:stormwind-city}暴风城{/link}。王国日渐富庶，自给自足，数百年间置身于北方诸国的纷争之外。{link:holy-light}圣光{/link}信仰在这里深深扎根，{link:northshire-abbey}北郡{/link}的牧师们保存着它最古老的典籍。]=],
		},
		{
			title = "历史",
			text = [=[• {b}第一次战争。{/b}{link:orcs}兽人{/link}{link:horde}部落{/link}穿过{link:dark-portal}黑暗之门{/link}，进入南方的{link:swamp-of-sorrows}沼泽{/link}，{link:azeroth}艾泽拉斯{/link}王国独自承受了{link:first-war}第一次战争{/link}的全部重压。它的农场和村庄被焚毁。最终{link:stormwind-city}暴风城{/link}本身也陷落了，国王{link:llane-wrynn}莱恩·乌瑞恩{/link}在自己的城堡中被杀。{link:anduin-lothar}安度因·洛萨{/link}爵士率领幸存者渡海前往{link:lordaeron}洛丹伦{/link}，国王年幼的儿子{link:varian-wrynn}瓦里安{/link}也在其中。
• {b}第二次战争。{/b}洛萨的警告打动了国王{link:terenas-menethil}泰瑞纳斯·米奈希尔{/link}，他组建了{link:alliance}洛丹伦联盟{/link}。暴风城的流亡者在{link:second-war}第二次战争{/link}中与北方诸国并肩作战，直到部落被击溃。
• {b}重建。{/b}流亡者回到故乡，面对的是一片废墟。瓦里安加冕为王，{link:stonemasons-guild}石匠协会{/link}在瓦砾之上重建了这座城市。当{link:house-of-nobles}贵族院{/link}拒绝向石匠支付报酬时，骚乱充斥街头，王后{link:tiffin-wrynn}蒂芬·乌瑞恩{/link}死于混乱之中。石匠们被驱逐出城，{link:defias-brotherhood}迪菲亚兄弟会{/link}由此诞生。
• {b}第三次战争。{/b}当瘟疫摧毁洛丹伦时，暴风城躲过了{link:third-war}第三次战争{/link}最惨烈的部分。北方王国陷落后，暴风城成为联盟的首要力量。]=],
		},
		{
			title = "当今",
			text = [=[{link:stormwind-city}暴风城{/link}是一个没有国王的王国。{link:varian-wrynn}瓦里安·乌瑞恩{/link}已经失踪，无人知道他去了哪里。大领主{link:bolvar-fordragon}伯瓦尔·弗塔根{/link}以年幼王子{link:anduin-wrynn}安度因·乌瑞恩{/link}的名义摄政。在宫廷中，{link:katrana-prestor}卡特拉娜·普瑞斯托{/link}女士赢得了贵族们的青睐，也赢得了摄政王的诸多信任。军队已远征他乡，王国的腹地只能依靠单薄的守军和志愿者来守卫。{link:westfall}西部荒野{/link}已落入{link:defias-brotherhood}迪菲亚{/link}之手。{link:riverpaw-gnolls}豺狼人{/link}和{link:kobolds}狗头人{/link}侵扰{link:elwynn-forest}艾尔文{/link}，{link:blackrock-clan}黑石氏族{/link}的{link:orcs}兽人{/link}进逼{link:redridge-mountains}赤脊山{/link}，{link:duskwood}暮色森林{/link}中亡者行走。{link:si-7}军情七处{/link}的特工在暗中行动，但王国的麻烦众多，守护者却寥寥无几。]=],
		},
	},
})

Translate("zhCN", "arathor", {
	title = "阿拉索",
	sections = {
		{
			title = "概述",
			text = [=[阿拉索是{link:humans}人类{/link}的第一个国家。它在与{link:trolls}巨魔{/link}的战争中锻造而成，又因与精灵结盟而得救。北方和南方的每一个人类王国都源于它。阿拉索本身已消亡一千多年，但凡有人类统治的地方，人们仍铭记着它的血脉与旗帜。]=],
		},
		{
			title = "起源",
			text = [=[在{link:dark-portal}黑暗之门{/link}开启前将近三千年，北方的{link:humans}人类{/link}部族四分五裂，彼此征战。阿曼尼{link:trolls}巨魔{/link}毫不留情地袭击他们。随后，{link:arathi-highlands}阿拉希{/link}部族的军阀{link:thoradin}索拉丁{/link}下定决心：人类必须团结，否则就将灭亡。他通过联姻、承诺和刀剑，将各部族统一在一面旗帜之下。他将自己的国度命名为阿拉索，并在至今仍以阿拉希为名的{link:razorfen-downs}高地{/link}上建起了都城——要塞之城激流城。]=],
		},
		{
			title = "历史",
			text = [=[• {b}巨魔战争。{/b}当阿曼尼人进攻{link:quel-thalas}奎尔萨拉斯{/link}时，精灵派遣使者前往激流城。作为换取阿拉索刀剑的代价，他们同意向一百名{link:humans}人类{/link}传授{link:arcane-magic}魔法{/link}之道。精灵与人类携手，在{link:alterac-mountains}奥特兰克山脉{/link}脚下击溃了阿曼尼人。{link:troll-wars}巨魔战争{/link}就此结束，精灵向{link:thoradin}索拉丁{/link}的血脉立誓永结友谊。
• {b}扩张。{/b}索拉丁之后，阿拉索的人民远远越出了激流城。他们建立了{link:dalaran}达拉然{/link}、{link:gilneas}吉尔尼斯{/link}的港口、岛国{link:kul-tiras}库尔提拉斯{/link}、山中的奥特兰克王座，以及富饶的{link:lordaeron}洛丹伦{/link}。每座城市都日益强大，也日益自作主张。
• {b}{link:great-sundering}分裂{/link}。{/b}激流城土地贫瘠，贸易稀少，逐渐失去了控制力。它的大家族北迁至洛丹伦。{link:arathi-highlands}阿拉希{/link}血脉的最后继承人向南航行，建立了后来成为{link:kingdom-of-stormwind}暴风王国{/link}的国度。激流城留给了少数几个统治家族，他们将其更名为{link:stromgarde-keep}激流堡{/link}。帝国已化为七大王国。]=],
		},
		{
			title = "当今",
			text = [=[阿拉索只在它的继承者身上延续。七大王国曾在{link:alliance}洛丹伦联盟{/link}中再度联合，由{link:thoradin}索拉丁{/link}的最后一位后裔{link:anduin-lothar}安度因·洛萨{/link}统领。如今，激流城所在的{link:razorfen-downs}高地{/link}已是一片废墟，{link:orcs}兽人{/link}、{link:trolls}巨魔{/link}、{link:ogres}食人魔{/link}和{link:syndicate}辛迪加{/link}的匪徒在此争夺。]=],
		},
	},
})

Translate("zhCN", "lordaeron", {
	title = "洛丹伦",
	sections = {
		{
			title = "概述",
			text = [=[洛丹伦曾是{link:humans}人类{/link}王国中最强大的一个。它的国王们从{link:tirisfal-glades}提瑞斯法{/link}林间的首都统治北方大地，并领导了在{link:second-war}第二次战争{/link}中拯救人类的{link:alliance}联盟{/link}。它在{link:third-war}第三次战争{/link}中陷落，遭到自己王子的背叛。如今它的土地已成为亡者的王国。]=],
		},
		{
			title = "起源",
			text = [=[在{link:arathor}阿拉索{/link}时代，拓荒者占据了{link:tirisfal-glades}提瑞斯法{/link}肥沃的林间空地，并以{link:troll-wars}巨魔战争{/link}中的一位将军洛丹之名为这片土地命名。激流城衰落后，许多贵族家族将产业北迁至这片丰饶的田野。他们使洛丹伦成为一个独立的王国，其疆域迅速扩张。洛丹伦也是一片信仰之地。朝圣者从远方来到它的修道院，在{link:holy-light}圣光{/link}中寻求治愈与智慧。]=],
		},
		{
			title = "历史",
			text = [=[• {b}{link:second-war}第二次战争{/link}。{/b}当{link:anduin-lothar}安度因·洛萨{/link}爵士将{link:stormwind-city}暴风城{/link}的幸存者带到北方时，国王{link:terenas-menethil}泰瑞纳斯·米奈希尔{/link}收留了他们。随后他召集{link:humans}人类{/link}诸王国的统治者，组建了{link:alliance}洛丹伦联盟{/link}。在洛萨的指挥下，联盟将{link:horde}部落{/link}逐回了{link:dark-portal}黑暗之门{/link}。
• {b}不安的和平。{/b}战败的{link:orcs}兽人{/link}被关押在洛丹伦各地的{link:internment-camps}收容所{/link}中，耗费巨大。这一负担使联盟{link:great-sundering}分裂{/link}。{link:gilneas}吉尔尼斯{/link}、{link:stromgarde-keep}激流堡{/link}和{link:quel-thalas}奎尔萨拉斯{/link}相继退出，泰瑞纳斯的王国也因此削弱。
• {b}瘟疫。{/b}在{link:third-war}第三次战争{/link}中，{link:cult-of-the-damned}诅咒教派{/link}借北方的谷物散播瘟疫，死者成千上万地复生。王子{link:arthas-menethil}阿尔萨斯·米奈希尔{/link}在{link:culling-of-stratholme}净化{/link}中焚毁了染疫的斯坦索姆城，随后追击瘟疫的主使者直至诺森德。他以{link:scourge}天灾军团{/link}死亡骑士的身份归来，在王座上弑杀了自己的父亲。这就是{link:fall-of-lordaeron}洛丹伦的陷落{/link}。]=],
		},
		{
			title = "当今",
			text = [=[洛丹伦是一个尸骸之国。{link:scourge}天灾军团{/link}占据着瘟疫之地。在首都的废墟之下，{link:sylvanas-windrunner}希尔瓦娜斯·风行者{/link}的{link:forsaken}被遗忘者{/link}以{link:undercity}幽暗城{/link}为家。{link:scarlet-crusade}血色十字军{/link}焚烧一切被怀疑染疫的人，而{link:argent-dawn}银色黎明{/link}则与所有愿意出力的人一同对抗天灾军团。这里再也没有活人的国王统治。]=],
		},
	},
})

Translate("zhCN", "gilneas", {
	title = "吉尔尼斯",
	sections = {
		{
			title = "概述",
			text = [=[吉尔尼斯是一个骄傲的{link:humans}人类{/link}王国，位于{link:silverpine-forest}银松森林{/link}以南一座崎岖的半岛上。它的人民坚韧而自立，它的军队曾是七国中最强大的之一。{link:second-war}第二次战争{/link}之后，它的国王在一道巨墙之后将王国与世隔绝。墙后发生着什么，外人无从知晓。]=],
		},
		{
			title = "起源",
			text = [=[吉尔尼斯是{link:troll-wars}巨魔战争{/link}之后{link:arathor}阿拉索{/link}人民建立的城邦之一。它的拓荒者沿海岸修建了坚固的港口，其中最大胆的水手后来建立了{link:kul-tiras}库尔提拉斯{/link}。吉尔尼斯无法与库尔提拉斯的舰队匹敌，便转而经营贸易和武备。它的士兵被认为不逊于阿拉索的任何军队。]=],
		},
		{
			title = "历史",
			text = [=[• {b}{link:second-war}第二次战争{/link}。{/b}国王{link:genn-greymane}吉恩·格雷迈恩{/link}加入了洛丹伦联盟，但对它并无好感。他相信吉尔尼斯能够独自保卫自己，因而将军队留在本土附近。
• {b}{link:the-greymane-wall}格雷迈恩之墙{/link}。{/b}战后，{link:internment-camps}兽人收容所{/link}的开销激怒了他。格雷迈恩让吉尔尼斯退出了{link:alliance}联盟{/link}。随后他在王国的北部边境筑起一道巨墙，并关闭了城门。这道墙穿过他自己贵族的领地，将{link:pyrewood-village}焚木村{/link}和{link:ambermill}安伯米尔{/link}等村庄留在了墙外。
• {b}{link:third-war}第三次战争{/link}。{/b}当瘟疫席卷{link:lordaeron}洛丹伦{/link}时，吉尔尼斯的城门依然紧闭。没有一支军队从南方出来援助这个垂死的王国。]=],
		},
		{
			title = "当今",
			text = [=[{link:the-greymane-wall}格雷迈恩之墙{/link}依然屹立，城门依然紧闭。在墙外的{link:silverpine-forest}银松森林{/link}，{link:scourge}天灾军团{/link}与{link:forsaken}被遗忘者{/link}争夺着北方的故土。被留在墙外的村民只能自谋生路。墙内的王国如今怎样，无人知晓。]=],
		},
	},
})

Translate("zhCN", "kul-tiras", {
	title = "库尔提拉斯",
	sections = {
		{
			title = "概述",
			text = [=[库尔提拉斯是无尽之海中的一个岛国，位于卡兹莫丹以西。它是一个水手和造船匠的国度，它的海军曾是世界上最强大的。普罗德摩尔家族为它产生了历代海军将领，它的港口则派出了载着{link:alliance}联盟{/link}奔赴战场的舰队。]=],
		},
		{
			title = "起源",
			text = [=[来自{link:gilneas}吉尔尼斯{/link}的水手在南方发现了一座盛产矿石和木材的大岛。其中一些人留了下来，在那里建立了一个海上据点，后来发展成为一个独立的王国。库尔提拉斯靠捕鱼和贸易兴盛起来。它的商船队航行于已知世界的每一处海岸，在{link:arathor}阿拉索{/link}时代，它拥有帝国最庞大的海军。]=],
		},
		{
			title = "历史",
			text = [=[• {b}{link:second-war}第二次战争{/link}。{/b}海军上将{link:daelin-proudmoore}戴林·普罗德摩尔{/link}率领库尔提拉斯的舰队加入了{link:alliance}洛丹伦联盟{/link}。他的战舰在海上与{link:orcs}兽人{/link}舰队交战，并保障了联盟军队的补给。王国为此付出了惨重的舰船和人员代价。
• {b}不安的和平。{/b}战后联盟衰弱时，库尔提拉斯仍对它保持忠诚，但越来越多地退回到自身事务之中。
• {b}{link:theramore-isle}塞拉摩{/link}。{/b}{link:third-war}第三次战争{/link}之后，戴林的女儿{link:jaina-proudmoore}吉安娜·普罗德摩尔{/link}率领北方的幸存者前往{link:kalimdor}卡利姆多{/link}，在那里与{link:thrall}萨尔{/link}的兽人缔结了和平。戴林无法接受。他率舰队前来消灭{link:horde}部落{/link}，在塞拉摩城下的战斗中阵亡。]=],
		},
		{
			title = "当今",
			text = [=[库尔提拉斯远在大海彼岸，很少参与大陆上的事务。在{link:kalimdor}卡利姆多{/link}的海岸，库尔提拉斯海军陆战队仍驻守着{link:the-barrens}贫瘠之地{/link}的{link:northwatch-hold}北方城堡{/link}和{link:durotar}杜隆塔尔{/link}的{link:tiragarde-keep}提拉加德城堡{/link}。他们没有原谅{link:horde}部落{/link}害死了他们的海军上将。]=],
		},
	},
})

Translate("zhCN", "dalaran", {
	title = "达拉然",
	sections = {
		{
			title = "概述",
			text = [=[达拉然是{link:city-of-dalaran}法师之城{/link}。它是{link:arathor}阿拉索{/link}第一个自治的城邦，两千多年来一直是{link:humans}人类{/link}魔法的中心。它紫色的高塔矗立在洛丹米尔湖畔，直到{link:scourge}天灾军团{/link}和{link:burning-legion}燃烧军团{/link}将其摧毁。如今达拉然已在{link:alterac-mountains}奥特兰克山脉{/link}重新崛起，由法师们统治。]=],
		},
		{
			title = "起源",
			text = [=[达拉然起初是{link:arathor}阿拉索{/link}中部的一个贸易站。它迅速发展，成为帝国法师的避难所，因为平民百姓并不信任他们。在法师阿多甘的领导下，这座城市从激流城手中赢得了自由，由术士们治理。他们鲁莽的魔法引起了恶魔的注意。为了暗中与恶魔作战，达拉然的法师与{link:quel-thalas}奎尔萨拉斯{/link}的精灵建立了{link:tirisfal-glades}提瑞斯法{/link}{link:shadow-council}议会{/link}，议会的守护者世代保卫着世界。后来，城中的法师组成了{link:kirin-tor}肯瑞托{/link}，并成为这座城市的统治者。]=],
		},
		{
			title = "历史",
			text = [=[• {b}{link:second-war}第二次战争{/link}。{/b}达拉然加入了{link:alliance}洛丹伦联盟{/link}，派出法师与{link:orcs}兽人{/link}作战。战后，它的巫师们在{link:nethergarde-keep}守望堡{/link}监视着{link:dark-portal}黑暗之门{/link}。
• {b}{link:third-war}第三次战争{/link}。{/b}曾是达拉然法师的死灵法师{link:kel-thuzad}克尔苏加德{/link}创立了{link:cult-of-the-damned}诅咒教派{/link}。在他的授意下，{link:arthas-menethil}阿尔萨斯·米奈希尔{/link}率领{link:scourge}天灾军团{/link}进攻这座城市，夺取了{link:medivh}麦迪文{/link}的魔法书。借助这本书，{link:archimonde}阿克蒙德{/link}被召唤到了这个世界。这位恶魔领主仅用一道法术便摧毁了达拉然，使其沦为废墟。
• {b}重建。{/b}幸存的法师回到废墟。他们在城市上空升起一道巨大的紫色屏障，在屏障的庇护下重建了城市，将其隐藏于世人眼前。]=],
		},
		{
			title = "当今",
			text = [=[重建后的达拉然矗立在{link:alterac-mountains}奥特兰克山脉{/link}，它的屏障已经消失。{link:kirin-tor}肯瑞托{/link}之外，尚无人能说清屏障为何落下。这座城市再度开放，街道上满是法师、商人和银行家。但城内并非一切安好。附魔出错，奥术构造体失控，恶魔能量在街头涌动。肯瑞托十分骄傲，不愿承认自己需要帮助。]=],
		},
	},
})

Translate("zhCN", "kirin-tor", {
	title = "肯瑞托",
	sections = {
		{
			title = "概述",
			text = [=[肯瑞托是{link:dalaran}达拉然{/link}的法师，也是那座城市的统治者。他们是{link:humans}人类{/link}魔法的守护者：它的学者、它的裁判者和它的看守人。长久以来，他们宣称有权监视人类土地上施放的每一道法术，并且小心翼翼地守护着自己的秘密。]=],
		},
		{
			title = "起源",
			text = [=[当{link:arathor}阿拉索{/link}帝国开始瓦解时，{link:dalaran}达拉然{/link}的法师组成了一个派系，研究并记录{link:humans}人类{/link}已知的每一种法术和魔法遗物。这个派系就是肯瑞托。它逐渐成为城市的统治组织，由其最杰出成员组成的{link:shadow-council}议会{/link}领导。他们在紫罗兰城堡中裁定哪些魔法可以修习，哪些必须禁止。]=],
		},
		{
			title = "历史",
			text = [=[• {b}守护者。{/b}数百年来，肯瑞托与{link:tirisfal-glades}提瑞斯法{/link}{link:shadow-council}议会{/link}合作，后者挑选暗中与恶魔作战的守护者。最后一位守护者是{link:medivh}麦迪文{/link}。
• {b}{link:second-war}第二次战争{/link}。{/b}肯瑞托的法师为{link:alliance}洛丹伦联盟{/link}而战。战后，他们在{link:dark-portal}黑暗之门{/link}附近修建了{link:nethergarde-keep}守望堡{/link}，以监视门后那片残破的土地。
• {b}{link:third-war}第三次战争{/link}。{/b}肯瑞托曾因法师{link:kel-thuzad}克尔苏加德{/link}研究死灵术而将其驱逐。他作为{link:cult-of-the-damned}诅咒教派{/link}的首领归来，他的瘟疫毁灭了{link:lordaeron}洛丹伦{/link}。该组织的领袖大法师{link:brother-anton}安东{/link}尼达斯在{link:scourge}天灾军团{/link}攻占{link:dalaran}达拉然{/link}时被杀。
• {b}狼人。{/b}该组织的一名法师，{link:archmage-arugal}大法师阿鲁高{/link}，在{link:silverpine-forest}银松森林{/link}召唤了野蛮的狼人来对抗天灾军团。事实证明，它们与亡灵一样是一场灾祸。阿鲁高如今占据着{link:shadowfang-keep}影牙城堡{/link}，据说他已经失去了理智。]=],
		},
		{
			title = "当今",
			text = [=[肯瑞托已在{link:alterac-mountains}奥特兰克山脉{/link}重建了{link:dalaran}达拉然{/link}，而它的屏障已经落下。在城内，他们的法术失灵，构造体挣脱束缚，他们竭力维持着对自己街道的控制。他们的法师仍在{link:nethergarde-keep}守望堡{/link}值守，其中一些人则在{link:theramore-isle}塞拉摩{/link}辅佐{link:jaina-proudmoore}吉安娜·普罗德摩尔{/link}。]=],
		},
	},
})

Translate("zhCN", "quel-thalas", {
	title = "奎尔萨拉斯",
	sections = {
		{
			title = "概述",
			text = [=[奎尔萨拉斯是{link:high-elves}高等精灵{/link}的王国，位于{link:lordaeron}洛丹伦{/link}北部的森林中。数千年来，它是一片永恒之春的国度，由太阳之井的魔法滋养。在{link:third-war}第三次战争{/link}中，{link:scourge}天灾军团{/link}攻破了它的城门，玷污了它神圣的源泉。王国残存的部分如今沉寂而遥远。]=],
		},
		{
			title = "起源",
			text = [=[{link:great-sundering}大分裂{/link}之后，一群上层精灵流亡者因热衷魔法而被{link:night-elves}暗夜精灵{/link}放逐，离开了{link:kalimdor}卡利姆多{/link}。在达斯{link:farmer-ray}雷{/link}玛·逐日者的带领下，他们渡过大海，定居在{link:eastern-kingdoms}东部王国{/link}北部。他们在那里建立了奎尔萨拉斯，并创造了太阳之井——一处奥术能量的源泉。他们在森林四周安置了符文石，以向可能被吸引而来的恶魔隐藏他们的魔法。]=],
		},
		{
			title = "历史",
			text = [=[• {b}{link:troll-wars}巨魔战争{/link}。{/b}阿曼尼{link:trolls}巨魔{/link}几乎攻陷了这个年轻的王国。精灵向{link:arathor}阿拉索{/link}求援，向一百名{link:humans}人类{/link}传授魔法，以换取它的军队。双方携手击溃了阿曼尼人，精灵向{link:thoradin}索拉丁{/link}的血脉立誓永结友谊。
• {b}{link:second-war}第二次战争{/link}。{/b}当{link:horde}部落{/link}和阿曼尼人在森林中纵火时，国王安纳斯特里安·逐日者履行了昔日的承诺，加入了{link:alliance}洛丹伦联盟{/link}。战后，他认定联盟辜负了他的人民，于是退出了联盟。
• {b}{link:third-war}第三次战争{/link}。{/b}王子{link:arthas-menethil}阿尔萨斯·米奈希尔{/link}率领{link:scourge}天灾军团{/link}北上。游侠将军{link:sylvanas-windrunner}希尔瓦娜斯·风行者{/link}在每一道城门前与他作战，最终被杀。阿尔萨斯杀死了国王安纳斯特里安，并利用太阳之井将{link:kel-thuzad}克尔苏加德{/link}复活为巫妖。精灵王国的核心遭到了玷污。]=],
		},
		{
			title = "当今",
			text = [=[奎尔萨拉斯位于瘟疫之地以北，被{link:scourge}天灾军团{/link}与南方隔绝。很少有消息从那里传来。留在南方土地上的{link:high-elves}高等精灵{/link}分散成一个个小群体生活，例如{link:the-hinterlands}辛特兰{/link}{link:quel-danil-lodge}奎尔丹尼小屋{/link}的游侠。他们中的许多人为一个也许再也见不到的家园而哀伤。]=],
		},
	},
})

Translate("zhCN", "alliance", {
	title = "联盟",
	aliases = { "洛丹伦联盟" },
	sections = {
		{
			title = "概述",
			text = [=[联盟是各个民族为对抗共同的敌人而结成的同盟。{link:humans}人类{/link}、{link:dwarves}矮人{/link}、{link:gnomes}侏儒{/link}和{link:night-elves}暗夜精灵{/link}都是其中的成员。它诞生于{link:second-war}第二次战争{/link}，为对抗{link:orcs}兽人{/link}{link:horde}部落{/link}而建立，此后几经{link:great-sundering}分裂{/link}与重组。如今，它最强大的力量是{link:kingdom-of-stormwind}暴风王国{/link}和{link:kingdom-of-ironforge}铁炉堡王国{/link}。]=],
		},
		{
			title = "起源",
			text = [=[当{link:stormwind-city}暴风城{/link}在{link:first-war}第一次战争{/link}中陷落时，{link:anduin-lothar}安度因·洛萨{/link}爵士将幸存者带到{link:lordaeron}洛丹伦{/link}，并警告说{link:horde}部落{/link}将会北上。国王{link:terenas-menethil}泰瑞纳斯·米奈希尔{/link}听从了他的警告。他召集{link:humans}人类{/link}诸王国的统治者，将他们结成洛丹伦联盟，由洛萨担任最高统帅。{link:ironforge}铁炉堡{/link}的{link:dwarves}矮人{/link}、{link:gnomeregan}诺莫瑞根{/link}的{link:gnomes}侏儒{/link}和{link:quel-thalas}奎尔萨拉斯{/link}的{link:high-elves}高等精灵{/link}也加入了联盟。]=],
		},
		{
			title = "历史",
			text = [=[• {b}{link:second-war}第二次战争{/link}。{/b}联盟在北方各地迎战{link:horde}部落{/link}，将其一路逼退至{link:blackrock-mountain}黑石{/link}塔。{link:anduin-lothar}洛萨{/link}在最后的战斗中阵亡，他的副官{link:turalyon}图拉扬{/link}领导了最终的胜利。幸存的{link:orcs}兽人{/link}被赶进了{link:internment-camps}收容所{/link}。
• {b}{link:great-sundering}分裂{/link}。{/b}收容所的开销和旧日的积怨使联盟分裂。{link:gilneas}吉尔尼斯{/link}、{link:stromgarde-keep}激流堡{/link}和{link:quel-thalas}奎尔萨拉斯{/link}相继退出。{link:alterac-mountains}奥特兰克{/link}此前已将联盟出卖给部落，并被剥夺了王冠。
• {b}{link:third-war}第三次战争{/link}。{/b}瘟疫和{link:scourge}天灾军团{/link}摧毁了{link:lordaeron}洛丹伦{/link}。{link:jaina-proudmoore}吉安娜·普罗德摩尔{/link}率领幸存者西渡{link:kalimdor}卡利姆多{/link}，在那里，{link:humans}人类{/link}、兽人和{link:night-elves}暗夜精灵{/link}在{link:battle-of-mount-hyjal}海加尔山之战{/link}中并肩作战。
• {b}新联盟。{/b}此后数年间，{link:stormwind-city}暴风城{/link}举起了洛丹伦落下的旗帜。{link:ironforge}铁炉堡{/link}与它站在一起，失去{link:gnomeregan}诺莫瑞根{/link}的{link:gnomes}侏儒{/link}栖身于{link:dwarves}矮人{/link}之中，{link:darnassus}达纳苏斯{/link}的暗夜精灵也加入了联盟。]=],
		},
		{
			title = "当今",
			text = [=[联盟在纸面上强大，实际上却捉襟见肘。国王{link:varian-wrynn}瓦里安·乌瑞恩{/link}已经失踪，大领主{link:bolvar-fordragon}伯瓦尔·弗塔根{/link}作为摄政王统治{link:stormwind-city}暴风城{/link}。国王{link:magni-bronzebeard}麦格尼·铜须{/link}统治{link:ironforge}铁炉堡{/link}。{link:tyrande-whisperwind}泰兰德·语风{/link}领导{link:night-elves}暗夜精灵{/link}，{link:jaina-proudmoore}吉安娜·普罗德摩尔{/link}镇守{link:theramore-isle}塞拉摩{/link}。他们的士兵在{link:ashenvale}灰谷{/link}和{link:the-barrens}贫瘠之地{/link}与{link:horde}部落{/link}作战，在{link:lordaeron}洛丹伦{/link}与{link:scourge}天灾军团{/link}作战，还要在本土对付十几个较小的敌人。与{link:orcs}兽人{/link}和平相处常被提起，却很少被信任。]=],
		},
	},
})

Translate("zhCN", "horde", {
	title = "部落",
	sections = {
		{
			title = "概述",
			text = [=[部落是{link:orcs}兽人{/link}及其盟友结成的同盟：{link:darkspear-trolls}暗矛巨魔{/link}、{link:tauren}牛头人{/link}和{link:forsaken}被遗忘者{/link}。它诞生于另一个世界，是恶魔的工具。它进入{link:azeroth}艾泽拉斯{/link}，焚毁诸国，最终被击溃。随后，它在一位年轻的酋长领导下重生，成为一个追求自由的民族。它的首都是位于红色土地{link:durotar}杜隆塔尔{/link}的{link:orgrimmar}奥格瑞玛{/link}。]=],
		},
		{
			title = "起源",
			text = [=[在德拉诺世界，{link:orcs}兽人{/link}曾是一个由氏族和萨满组成的骄傲民族。{link:burning-legion}燃烧军团{/link}的恶魔{link:kil-jaeden}基尔加丹{/link}决意将他们变成自己的武器。他先通过萨满{link:ner-zhul}耐奥祖{/link}，再通过术士{link:gul-dan}古尔丹{/link}，向他们传授{link:fel-magic}邪能魔法{/link}。最终，各氏族酋长饮下了恶魔{link:mannoroth}玛诺洛斯{/link}的血，一股燃烧的嗜血之欲将他们与燃烧军团捆绑在一起。他们联合成一个部落，消灭了德莱尼人，而他们的世界也在脚下枯萎。]=],
		},
		{
			title = "历史",
			text = [=[• {b}{link:first-war}第一次战争{/link}。{/b}部落穿过{link:dark-portal}黑暗之门{/link}，入侵并摧毁了{link:azeroth}艾泽拉斯{/link}王国。{link:stormwind-city}暴风城{/link}陷落，国王{link:llane-wrynn}莱恩·乌瑞恩{/link}被杀。
• {b}{link:second-war}第二次战争{/link}。{/b}在大酋长{link:orgrim-doomhammer}奥格瑞姆·毁灭之锤{/link}的率领下，部落带着{link:ogres}食人魔{/link}、阿曼尼{link:trolls}巨魔{/link}、地精和被奴役的红龙向北进军。{link:alliance}联盟{/link}击败了它，大部分幸存的{link:orcs}兽人{/link}被关进了{link:internment-camps}收容所{/link}。
• {b}新的部落。{/b}在收容所中，兽人陷入了一种奇怪的消沉。一个作为奴隶长大的年轻兽人{link:thrall}萨尔{/link}挣脱了束缚，学会了萨满的古老之道，并解放了他的族人。毁灭之锤在他身旁战死，将自己的战锤和头衔传给了他。
• {b}{link:third-war}第三次战争{/link}。{/b}萨尔听从先知{link:medivh}麦迪文{/link}的指引，率领部落前往{link:kalimdor}卡利姆多{/link}。他在那里赢得了{link:darkspear-trolls}暗矛巨魔{/link}和{link:cairne-bloodhoof}凯恩·血蹄{/link}的{link:tauren}牛头人{/link}的友谊。{link:grom-hellscream}格罗姆·地狱咆哮{/link}杀死了{link:mannoroth}玛诺洛斯{/link}，将兽人从其血之诅咒中解放出来。部落在{link:battle-of-mount-hyjal}海加尔山之战{/link}中与联盟并肩作战。]=],
		},
		{
			title = "当今",
			text = [=[{link:thrall}萨尔{/link}作为大酋长在{link:orgrimmar}奥格瑞玛{/link}统治，这座城市以毁灭之锤之名命名以示纪念。{link:cairne-bloodhoof}凯恩{/link}在{link:thunder-bluff}雷霆崖{/link}领导{link:tauren}牛头人{/link}，{link:vol-jin}沃金{/link}领导{link:darkspear-trolls}暗矛巨魔{/link}，{link:sylvanas-windrunner}希尔瓦娜斯·风行者{/link}则率领{link:lordaeron}洛丹伦{/link}的{link:forsaken}被遗忘者{/link}站在部落一边。与{link:theramore-isle}塞拉摩{/link}的和平仍在维持，但岌岌可危。在{link:ashenvale}灰谷{/link}，{link:orcs}兽人{/link}砍伐{link:night-elves}暗夜精灵{/link}森林中的树木，为此血流不止。{link:kul-tiras}库尔提拉斯{/link}海军陆战队把守着海岸，{link:centaurs}半人马{/link}和{link:quilboar}野猪人{/link}在每一处边境施压，而恶魔教派{link:burning-blade}火刃氏族{/link}正在{link:durotar}杜隆塔尔{/link}内部滋生蔓延。]=],
		},
	},
})

Translate("zhCN", "burning-legion", {
	title = "燃烧军团",
	sections = {
		{
			title = "概述",
			text = [=[燃烧军团是一支庞大的恶魔大军，已经毁灭了无数世界。它的主人是{link:sargeras}萨格拉斯{/link}，一位堕落的泰坦，他曾守护造物，如今却要将其毁灭。燃烧军团曾三度将魔爪伸向{link:azeroth}艾泽拉斯{/link}。三度都被击退，代价惨重。]=],
		},
		{
			title = "起源",
			text = [=[{link:sargeras}萨格拉斯{/link}曾是世界的塑造者——泰坦之中最伟大的勇士。在与扭曲虚空中的恶魔进行的漫长战争中，他逐渐相信一切造物都有缺陷，必须付之一炬。他背叛了自己的同类，聚集起一支恶魔大军来实现这一目标。他最早腐化的种族之一是艾瑞达人，其领袖{link:kil-jaeden}基尔加丹{/link}和{link:archimonde}阿克蒙德{/link}成为他的首席副官。]=],
		},
		{
			title = "历史",
			text = [=[• {b}上古战争。{/b}{link:queen-azshara}艾萨拉女王{/link}和她的上层精灵通过{link:well-of-eternity}永恒之井{/link}将燃烧军团引入了这个世界。{link:night-elves}暗夜精灵{/link}在{link:malfurion-stormrage}玛法里奥·怒风{/link}的领导下，在{link:war-of-the-ancients}上古战争{/link}中奋起反击。永恒之井的毁灭在{link:great-sundering}大分裂{/link}中撕裂了大陆，并切断了恶魔的通道。
• {b}部落。{/b}随后，{link:kil-jaeden}基尔加丹{/link}腐化了德拉诺的{link:orcs}兽人{/link}，将他们变成一件武器。他所锻造的{link:horde}部落{/link}在{link:first-war}第一次战争{/link}和{link:second-war}第二次战争{/link}中被投向{link:azeroth}艾泽拉斯{/link}。
• {b}{link:third-war}第三次战争{/link}。{/b}燃烧军团创造了{link:scourge}天灾军团{/link}来为其铺路。瘟疫毁灭了{link:lordaeron}洛丹伦{/link}，{link:archimonde}阿克蒙德{/link}本人在{link:dalaran}达拉然{/link}被召唤到了这个世界。他向世界之树{link:nordrassil}诺达希尔{/link}进军。在{link:battle-of-mount-hyjal}海加尔山之战{/link}中，暗夜精灵、{link:humans}人类{/link}和兽人拖住了他，直到先祖之灵将他摧毁。]=],
		},
		{
			title = "当今",
			text = [=[{link:archimonde}阿克蒙德{/link}已死，但燃烧军团并未离开{link:azeroth}艾泽拉斯{/link}。恶魔仍出没于{link:felwood}费伍德森林{/link}被腐化的{link:moonglade}林地{/link}、{link:azshara}艾萨拉{/link}的废墟和{link:desolace}凄凉之地{/link}的荒原。{link:burning-blade}火刃氏族{/link}的教派在{link:orcs}兽人{/link}之中暗中为它们效力。在{link:blasted-lands}诅咒之地{/link}，{link:nethergarde-keep}守望堡{/link}的法师们监视着{link:dark-portal}黑暗之门{/link}，提防它们卷土重来的任何迹象。]=],
		},
	},
})

Translate("zhCN", "scourge", {
	title = "天灾军团",
	sections = {
		{
			title = "概述",
			text = [=[天灾军团是一支亡灵大军，由瘟疫唤起，受诺森德冰层中的巫妖王统治。在{link:third-war}第三次战争{/link}中，它毁灭了{link:lordaeron}洛丹伦{/link}王国，玷污了{link:quel-thalas}奎尔萨拉斯{/link}，并将{link:dalaran}达拉然{/link}夷为平地。它仍占据着北方的大片土地，仍渴求着生者。]=],
		},
		{
			title = "起源",
			text = [=[{link:orcs}兽人{/link}令他失望之后，{link:burning-legion}燃烧军团{/link}的{link:kil-jaeden}基尔加丹{/link}惩罚了它们昔日的萨满{link:ner-zhul}耐奥祖{/link}。他剥去了这名兽人的躯体，将其灵魂束缚在一套封入冰块的盔甲之中。随后，他将其投入诺森德，并称之为巫妖王。巫妖王的任务是在{link:humans}人类{/link}土地上散播亡灵瘟疫，为燃烧军团做好准备。巫妖王在冰封王座上以心灵触及生者，将野心勃勃者和走投无路者吸引到自己身边。]=],
		},
		{
			title = "历史",
			text = [=[• {b}瘟疫。{/b}法师{link:kel-thuzad}克尔苏加德{/link}听到了巫妖王的召唤，创立了{link:cult-of-the-damned}诅咒教派{/link}。瘟疫通过教派混入{link:lordaeron}洛丹伦{/link}北部的谷物中传播开来。吃下谷物的人死去，又作为亡灵复生。
• {b}陷落。{/b}王子{link:arthas-menethil}阿尔萨斯·米奈希尔{/link}追查瘟疫直至诺森德。他在那里拿起符文剑霜之哀伤，成为巫妖王的勇士。他归来后谋杀了自己的父亲，将洛丹伦交给了亡者。随后，他率领天灾军团穿过{link:quel-thalas}奎尔萨拉斯{/link}，在那里将克尔苏加德复活为巫妖，又前往{link:dalaran}达拉然{/link}，恶魔领主{link:archimonde}阿克蒙德{/link}在那里被召唤而来。
• {b}挣脱枷锁。{/b}阿克蒙德在{link:mount-hyjal}海加尔山{/link}陨落后，巫妖王的掌控减弱了。许多亡灵挣脱了束缚，{link:sylvanas-windrunner}希尔瓦娜斯·风行者{/link}率领他们成为{link:forsaken}被遗忘者{/link}。阿尔萨斯北上驰援巫妖王。]=],
		},
		{
			title = "当今",
			text = [=[天灾军团仍统治着瘟疫之地。{link:kel-thuzad}克尔苏加德{/link}以巫妖王之名发号施令，他的仆从占据着斯坦索姆废城、通灵学院中的死灵学校和许多沦陷的城镇。染疫的生物潜行于林间，憎恶守卫着{link:the-dead-acre}死亡之地{/link}。与之对抗的是{link:forsaken}被遗忘者{/link}、{link:scarlet-crusade}血色十字军{/link}和{link:argent-dawn}银色黎明{/link}，而这三方在其他任何事情上都意见不合。]=],
		},
	},
})

Translate("zhCN", "cult-of-the-damned", {
	title = "诅咒教派",
	sections = {
		{
			title = "概述",
			text = [=[诅咒教派是{link:scourge}天灾军团{/link}中由活人组成的祭司团。其成员崇拜巫妖王，心甘情愿地为他效力，期望死后获得永生。正是这个教派将瘟疫带入了{link:lordaeron}洛丹伦{/link}，它的死灵法师至今仍以巫妖王之名唤起死者。]=],
		},
		{
			title = "起源",
			text = [=[教派由{link:kel-thuzad}克尔苏加德{/link}创立，他是{link:kirin-tor}肯瑞托{/link}的一名法师，因研究被禁止的死灵术而被驱逐。他远赴诺森德，听到了巫妖王的声音。他以巫妖王先知的身份回到{link:lordaeron}洛丹伦{/link}。他在北方的穷人和{link:forsaken}被遗忘者{/link}之中宣扬一个新的社会，在那里人人平等，死亡也不再是终结。成千上万的人追随了他，却很少有人明白自己加入的是什么。]=],
		},
		{
			title = "历史",
			text = [=[• {b}瘟疫。{/b}教派通过{link:lordaeron}洛丹伦{/link}北部的粮仓散播亡灵瘟疫。被污染的谷物从{link:ruins-of-andorhal}安多哈尔{/link}运往各个村庄，死者开始复生。
• {b}{link:kel-thuzad}克尔苏加德{/link}的死亡与回归。{/b}王子{link:arthas-menethil}阿尔萨斯·米奈希尔{/link}在安多哈尔杀死了克尔苏加德。阿尔萨斯堕入巫妖王麾下后，将这位死灵法师的遗骸带到{link:quel-thalas}奎尔萨拉斯{/link}的太阳之井，将其复活为巫妖。
• {b}通灵学院。{/b}巴罗夫家族将他们位于{link:caer-darrow}凯尔达隆{/link}岛上的城堡献给了教派。在那里的通灵学院中，教派训练着新的死灵法师。]=],
		},
		{
			title = "当今",
			text = [=[教派在瘟疫之地依然强大。它的侍僧在斯坦索姆和{link:ruins-of-andorhal}安多哈尔{/link}的废墟中效力。在通灵学院，黑暗院长加丁向自愿的学生传授死灵术。教派的特工仍在生者之间活动，寻找新的信徒和散播瘟疫的新途径。]=],
		},
	},
})

Translate("zhCN", "scarlet-crusade", {
	title = "血色十字军",
	sections = {
		{
			title = "概述",
			text = [=[血色十字军是{link:holy-light}圣光{/link}的一个武装教团，誓要消灭{link:lordaeron}洛丹伦{/link}的亡灵。它诞生于{link:third-war}第三次战争{/link}的悲痛之中，已变得严酷而狂热。十字军不信任任何人。它猎杀{link:scourge}天灾军团{/link}，也猎杀{link:forsaken}被遗忘者{/link}，并将任何外人视为可能的瘟疫携带者。]=],
		},
		{
			title = "起源",
			text = [=[{link:fall-of-lordaeron}洛丹伦陷落{/link}之后，{link:uther-the-lightbringer}光明使者乌瑟尔{/link}创立的圣骑士骑士团支离破碎，许多骑士已经死去。幸存者聚集在旧骑士团的圣骑士、大十字军战士赛丹·达索汉麾下。他们发誓要清除{link:lordaeron}洛丹伦{/link}瘟疫的一切痕迹，并以猩红为自己的颜色。许多因{link:scourge}天灾军团{/link}而失去一切的人纷纷投奔他们的旗帜。]=],
		},
		{
			title = "历史",
			text = [=[• {b}十字军。{/b}十字军以巨大的勇气和极少的怜悯在北方各地与{link:scourge}天灾军团{/link}作战。它在{link:tirisfal-glades}提瑞斯法林地{/link}修筑了{link:scarlet-monastery}血色修道院{/link}，并加固了{link:hearthglen}壁炉谷{/link}镇和{link:tyr-s-hand}提尔之手{/link}城。
• {b}狂热者。{/b}随着时间推移，十字军的热忱变成了残忍。它开始清洗任何被怀疑染疫的人，它的审判官在生者之中令人畏惧。一些成员无法忍受它的变化。他们离开了十字军，创立了{link:argent-dawn}银色黎明{/link}。]=],
		},
		{
			title = "当今",
			text = [=[血色十字军占据着{link:tirisfal-glades}提瑞斯法{/link}的修道院，{link:high-inquisitor-whitemane}大检察官怀特迈恩{/link}和{link:scarlet-commander-mograine}血色十字军指挥官莫格莱尼{/link}在那里统领其骑士。它的部队还占据着{link:western-plaguelands}西瘟疫之地{/link}的{link:hearthglen}壁炉谷{/link}和{link:eastern-plaguelands}东瘟疫之地{/link}的{link:tyr-s-hand}提尔之手{/link}。它的巡逻队在任何地方发现{link:forsaken}被遗忘者{/link}都会将其烧死。它的狂热是真实的，它的力量也是。它是否仍在侍奉{link:holy-light}圣光{/link}，这个问题连它自己的成员都已不敢再问。]=],
		},
	},
})

Translate("zhCN", "argent-dawn", {
	title = "银色黎明",
	sections = {
		{
			title = "概述",
			text = [=[银色黎明是一个誓要保卫{link:azeroth}艾泽拉斯{/link}的组织，对抗{link:scourge}天灾军团{/link}、{link:burning-legion}燃烧军团{/link}以及其他一切妄图毁灭世界的力量。它独立于国王和酋长之外。它欢迎任何愿意与亡灵作战的人，无论其种族或旗帜，因此{link:orcs}兽人{/link}、{link:humans}人类{/link}、{link:dwarves}矮人{/link}乃至{link:forsaken}被遗忘者{/link}都是它的朋友。]=],
		},
		{
			title = "起源",
			text = [=[银色黎明脱胎于{link:scarlet-crusade}血色十字军{/link}。随着十字军日益狂热，一些成员开始担心其领袖已经迷失了方向。马克斯韦尔·{link:lord-maxwell-tyrosus}泰罗索斯{/link}勋爵等人拒绝继续追随。他们离开了十字军，建立了一个新的组织，忠于他们所理解的{link:holy-light}圣光{/link}教诲。它的第一位领袖是{link:farmer-ray}雷{/link}蒙德·乔治勋爵。]=],
		},
		{
			title = "历史",
			text = [=[• {b}北方之战。{/b}从成立之初，银色黎明就在瘟疫之地各处与{link:scourge}天灾军团{/link}作战，常常兵员稀少，补给更少。
• {b}向所有人敞开的组织。{/b}与十字军不同，银色黎明不问盟友生前是谁。它同样接受{link:alliance}联盟{/link}和{link:horde}部落{/link}的援助，只以行动评判每一个人。]=],
		},
		{
			title = "当今",
			text = [=[马克斯韦尔·{link:lord-maxwell-tyrosus}泰罗索斯{/link}勋爵在{link:eastern-plaguelands}东瘟疫之地{/link}的{link:light-s-hope-chapel}圣光之愿礼拜堂{/link}领导银色黎明。它的营地遍布瘟疫之地，它的使者在遥远的城市中等待，以召集盟友。银色黎明奖赏那些带回所消灭亡者之证明的人。它的成员说，与{link:scourge}天灾军团{/link}的战争不会仅凭任何一个国家赢得。]=],
		},
	},
})

Translate("zhCN", "defias-brotherhood", {
	title = "迪菲亚兄弟会",
	aliases = { "迪菲亚" },
	sections = {
		{
			title = "概述",
			text = [=[迪菲亚兄弟会是一支盗匪大军，它占领了{link:westfall}西部荒野{/link}，并劫掠{link:kingdom-of-stormwind}暴风王国{/link}的土地。其成员戴着红色头巾，从暗处出击。它的核心是那些重建了{link:stormwind-city}暴风城{/link}却从未得到报酬的石匠。他们要拿回自己应得的东西，然后夺取这座城市本身。]=],
		},
		{
			title = "起源",
			text = [=[{link:second-war}第二次战争{/link}之后，{link:edwin-vancleef}艾德温·范克里夫{/link}的{link:stonemasons-guild}石匠协会{/link}从灰烬中重建了{link:stormwind-city}暴风城{/link}。工程完成后，{link:house-of-nobles}贵族院{/link}拒绝支付他们报酬。石匠们发动了骚乱，王后{link:tiffin-wrynn}蒂芬·乌瑞恩{/link}在混乱中被杀。石匠们被逐出城市。在范克里夫的带领下，他们向西进入{link:westfall}西部荒野{/link}的丘陵和田野，在那里成为了迪菲亚兄弟会。]=],
		},
		{
			title = "历史",
			text = [=[• {b}征服{link:westfall}西部荒野{/link}。{/b}由于军队远在他乡，王室又保持沉默，兄弟会几乎未遇抵抗便占领了西部荒野。其成员将农民赶出土地，并将{link:moonbrook}月溪镇{/link}作为他们的据点。
• {b}兄弟会的触角。{/b}迪菲亚盗贼蔓延到{link:elwynn-forest}艾尔文{/link}、{link:redridge-mountains}赤脊山{/link}和{link:duskwood}暮色森林{/link}。{link:kobolds}狗头人{/link}偷来的{link:ginro-hearthkindle}金{/link}子流入他们的特工手中，他们的戒指上刻着{link:stonemasons-guild}石匠协会{/link}的旧标记。]=],
		},
		{
			title = "当今",
			text = [=[兄弟会在暗中统治着{link:westfall}西部荒野{/link}。在{link:moonbrook}月溪镇{/link}地下的{link:the-deadmines}死亡矿井{/link}中，{link:edwin-vancleef}范克里夫{/link}的石匠们正在建造一艘巨船，其用途秘而不宣。他们的{link:harvest-golems}收割傀儡{/link}在被夺走的田地上劳作，他们的匪帮控制着道路。只有{link:gryan-stoutmantle}治安官格里安·斯托曼{/link}领导的{link:sentinel-hill}哨兵岭{/link}人民军与之对抗。在{link:stormwind-city}暴风城{/link}的{link:the-stockade}监狱{/link}中，被俘的迪菲亚分子发动暴乱，占据了牢房。]=],
		},
	},
})

Translate("zhCN", "stonemasons-guild", {
	title = "石匠协会",
	sections = {
		{
			title = "概述",
			text = [=[石匠协会是在{link:second-war}第二次战争{/link}后重建{link:stormwind-city}暴风城{/link}的工匠团体。他们的技艺赋予了这座城市白色的城墙和高大的塔楼。王国对他们的背叛，使其石匠大师们变成了王国最危险的敌人。]=],
		},
		{
			title = "起源",
			text = [=[{link:stormwind-city}暴风城{/link}的流亡者从{link:lordaeron}洛丹伦{/link}归来时，发现他们的首都已成废墟。重建的工作落在了石匠们身上。他们的首领{link:edwin-vancleef}艾德温·范克里夫{/link}是一位天赋罕见的工匠，在他的领导下，协会在数年之内完成了本可能需要几代人才能完成的工作。今天屹立的这座城市大部分出自他们之手。]=],
		},
		{
			title = "历史",
			text = [=[• {b}背叛。{/b}工程完成后，{link:house-of-nobles}贵族院{/link}拒绝支付石匠们应得的报酬。石匠们提出抗议，抗议演变成了骚乱。王后{link:tiffin-wrynn}蒂芬·乌瑞恩{/link}在混乱中被杀。
• {b}流放。{/b}石匠们被逐出{link:stormwind-city}暴风城{/link}。{link:edwin-vancleef}范克里夫{/link}带领他们向西而去，他们在那里成为了{link:defias-brotherhood}迪菲亚兄弟会{/link}。建造城市的技艺被转而用于为盗贼修筑堡垒。]=],
		},
		{
			title = "当今",
			text = [=[旧协会的标记留存在{link:defias-brotherhood}迪菲亚{/link}的戒指上和{link:the-deadmines}死亡矿井{/link}的石工之中。在{link:elwynn-forest}艾尔文{/link}和{link:westfall}西部荒野{/link}各地，石匠们如今为兄弟会建造工事。{link:stormwind-city}暴风城{/link}的城墙依然屹立，是协会能力的最好证明。]=],
		},
		{
			title = "未载",
			text = [=[没有任何编年史记载那些没有追随{link:edwin-vancleef}范克里夫{/link}流亡的石匠后来怎样，也没有记载如今{link:stormwind-city}暴风城{/link}是否仍有石匠协会在运作。]=],
		},
	},
})

Translate("zhCN", "house-of-nobles", {
	title = "贵族院",
	sections = {
		{
			title = "概述",
			text = [=[贵族院是{link:stormwind-city}暴风城{/link}大领主们的{link:shadow-council}议会{/link}。其成员拥有土地、财富和古老的头衔，长久以来一直插手王国的国库和法律。正是他们拒绝向石匠付款，使王国走上了通往当今困境的道路。]=],
		},
		{
			title = "起源",
			text = [=[没有任何编年史记载贵族院最初何时召集。它与王国的贵族家族一样古老，历经烈火与流亡而延续下来。当{link:stormwind-city}暴风城{/link}在{link:second-war}第二次战争{/link}后重建时，贵族院站在年轻的国王{link:varian-wrynn}瓦里安·乌瑞恩{/link}身旁，它的声音在新宫廷中举足轻重。]=],
		},
		{
			title = "历史",
			text = [=[• {b}石匠的工钱。{/b}{link:stonemasons-guild}石匠协会{/link}在{link:edwin-vancleef}艾德温·范克里夫{/link}的领导下重建了首都。工程完成后，贵族院拒绝支付石匠们应得的报酬。石匠们的抗议演变成骚乱，王后{link:tiffin-wrynn}蒂芬·乌瑞恩{/link}死于暴乱之中。石匠们被流放，成为了{link:defias-brotherhood}迪菲亚兄弟会{/link}。
• {b}罪责。{/b}{link:stormwind-city}暴风城{/link}中许多人至今仍将王后之死和迪菲亚的出现归咎于贵族。而贵族们则归咎于石匠。]=],
		},
		{
			title = "当今",
			text = [=[{link:varian-wrynn}瓦里安国王{/link}离去后，贵族们对大领主{link:bolvar-fordragon}伯瓦尔·弗塔根{/link}的摄政有着巨大的影响力。{link:katrana-prestor}卡特拉娜·普瑞斯托{/link}女士已成为他们中的宠儿，她的建言在每一场辩论中都受到倾听。平民们抱怨说，{link:westfall}西部荒野{/link}在燃烧，领主们却在为税收争吵。摄政王必须让贵族们满意，而这并没有让他的任务变得更轻松。]=],
		},
	},
})

Translate("zhCN", "si-7", {
	title = "军情七处",
	sections = {
		{
			title = "概述",
			text = [=[军情七处是{link:kingdom-of-stormwind}暴风王国{/link}的秘密情报机构。它的特工是为王室默默效力的间谍、斥候和刺客。他们监视着王国的敌人，无论是城墙之外的还是城墙之内的。{link:stormwind-city}暴风城{/link}中很少有人了解他们，而这正是他们所希望的。]=],
		},
		{
			title = "起源",
			text = [=[没有任何编年史记载军情七处成立于何时，或是谁最先为它命名。早在{link:third-war}第三次战争{/link}之前，它就已为{link:stormwind-city}暴风城{/link}的国王们效力，它的特工始终远离宫廷的光芒行事。]=],
		},
		{
			title = "历史",
			text = [=[• {b}暗影之中。{/b}军情七处多年来一直在追猎王国隐藏的敌人。它监视敌对王国、国内的叛徒和危险的教派。其成员主要从{link:stormwind-city}暴风城{/link}的潜行者中招募，并在其总部接受训练。]=],
		},
		{
			title = "当今",
			text = [=[马迪亚斯·肖大师从位于{link:stormwind-city}暴风城{/link}{link:old-town}旧城区{/link}的总部领导军情七处。他的特工在{link:westfall}西部荒野{/link}各地追踪{link:defias-brotherhood}迪菲亚兄弟会{/link}，监视兄弟会的盟友，并汇报{link:forsaken}被遗忘者{/link}之中的异常动向。一些人在{link:theramore-isle}塞拉摩{/link}效力，守护{link:jaina-proudmoore}吉安娜·普罗德摩尔{/link}的统治。另一些人加入了{link:ravenholdt-manor}拉文霍德{/link}的潜行者，与{link:syndicate}辛迪加{/link}作战。国王离去，军队远征，肖的无声工作比以往任何时候都更加重要。]=],
		},
	},
})

Translate("zhCN", "explorers-league", {
	title = "探险者协会",
	sections = {
		{
			title = "概述",
			text = [=[探险者协会是一个以{link:ironforge}铁炉堡{/link}为基地的矮人学者和冒险家团体。其成员发掘遗物，绘制被遗忘的废墟，研究远古世界的奥秘。最重要的是，他们在探寻{link:dwarves}矮人种族{/link}的真正起源，并相信答案就埋藏在岩石之中。]=],
		},
		{
			title = "起源",
			text = [=[{link:dwarves}矮人{/link}一向深挖地底，而协会将挖掘变成了学问。它从{link:ironforge}铁炉堡{/link}的{link:hall-of-explorers}探险者大厅{/link}向世界各地派出探险队，并收集他们的发现。其成员珍视知识如同珍视黄{link:ginro-hearthkindle}金{/link}。他们以勇气著称，也同样以无视危险而闻名。]=],
		},
		{
			title = "历史",
			text = [=[• {b}大发掘。{/b}协会长久以来一直相信，{link:dwarves}矮人{/link}是由世界的塑造者泰坦以岩石塑造而成的。它的探险队在卡兹莫丹及更远的地方搜寻远古废墟，以寻找这一点的证据。
• {b}著名人物。{/b}其成员中有国王{link:magni-bronzebeard}麦格尼·铜须{/link}的弟弟{link:brann-bronzebeard}布莱恩·铜须{/link}，他是他那个时代最著名的探险家。]=],
		},
		{
			title = "当今",
			text = [=[大探险家{link:high-explorer-magellas}麦格拉斯{/link}从{link:hall-of-explorers}探险者大厅{/link}领导协会。它的挖掘场遍布世界各地：{link:loch-modan}洛克莫丹{/link}的{link:ironband-s-excavation-site}铁环挖掘场{/link}、{link:the-barrens}贫瘠之地{/link}的{link:bael-modan}巴尔莫丹{/link}，以及{link:badlands}废土{/link}的{link:uldaman}奥达曼{/link}废墟。在{link:wetlands}湿地{/link}，{link:whelgar-s-excavation-site}维尔加挖掘场{/link}发掘出了挖掘者们始料未及的东西。{link:troggs}石腭怪{/link}的袭击和对手的争夺困扰着许多挖掘场，但协会不会轻易放弃。]=],
		},
	},
})

Translate("zhCN", "cenarion-circle", {
	title = "塞纳里奥议会",
	sections = {
		{
			title = "概述",
			text = [=[塞纳里奥议会是德鲁伊的组织，是自然的守护者。其成员从大地和{link:emerald-dream}翡翠梦境{/link}中汲取力量，并誓言保护生机勃勃的世界。{link:shadow-council}议会{/link}以半神{link:cenarius}塞纳留斯{/link}命名。它长期以来是{link:night-elves}暗夜精灵{/link}的组织，如今也接纳了{link:tauren}牛头人{/link}成员。]=],
		},
		{
			title = "起源",
			text = [=[{link:night-elves}暗夜精灵{/link}的第一位德鲁伊是{link:malfurion-stormrage}玛法里奥·怒风{/link}，他由{link:cenarius}塞纳留斯{/link}亲自传授。在{link:war-of-the-ancients}上古战争{/link}中，玛法里奥和他的追随者以这门新技艺对抗{link:burning-legion}燃烧军团{/link}。{link:great-sundering}大分裂{/link}之后，德鲁伊成为暗夜精灵土地的守护者。数千年来，他们沉睡于{link:emerald-dream}翡翠梦境{/link}之中，只在需要之时才醒来。]=],
		},
		{
			title = "历史",
			text = [=[• {b}{link:third-war}第三次战争{/link}。{/b}德鲁伊被唤醒，再次面对{link:burning-legion}燃烧军团{/link}。他们在{link:battle-of-mount-hyjal}海加尔山之战{/link}中作战，世界之树{link:nordrassil}诺达希尔{/link}在那里被牺牲，以消灭{link:archimonde}阿克蒙德{/link}。
• {b}开放的{link:shadow-council}议会{/link}。{/b}此后数年间，议会接纳了{link:tauren}牛头人{/link}德鲁伊，其中第一位是{link:hamuul-runetotem}哈缪尔·符文图腾{/link}。它独立于{link:alliance}联盟{/link}和{link:horde}部落{/link}之外。]=],
		},
		{
			title = "当今",
			text = [=[{link:shadow-council}议会{/link}的中心是{link:moonglade}月光林地{/link}，一处神圣的{link:stranglethorn-vale}山谷{/link}，{link:cenarius}塞纳留斯{/link}之子{link:keeper-remulos}守护者雷姆洛斯{/link}在那里守望。它的德鲁伊照料着{link:kalimdor}卡利姆多{/link}的荒野，并努力治愈{link:felwood}费伍德森林{/link}的腐化。{link:malfurion-stormrage}玛法里奥{/link}已退入{link:emerald-dream}翡翠梦境{/link}。在他缺席期间，大德鲁伊{link:fandral-staghelm}范达尔·鹿盔{/link}领导着{link:darnassus}达纳苏斯{/link}的德鲁伊，那里已培育出一棵新的世界之树——{link:teldrassil}泰达希尔{/link}。]=],
		},
	},
})

Translate("zhCN", "earthen-ring", {
	title = "大地之环",
	sections = {
		{
			title = "概述",
			text = [=[大地之环是一个致力于{link:elements}元素{/link}平衡的萨满{link:shadow-council}议会{/link}。其成员聆听大地、火焰、水和空气之灵的声音，努力使这些力量保持和谐。大地之环超然于各国纷争之上。它关注的是世界本身。]=],
		},
		{
			title = "起源",
			text = [=[大地之环由{link:tauren}牛头人{/link}在很久以前创立，用以智慧地引导族人，并维持{link:elements}元素{/link}之灵之间的和平。它的长老们世代召开{link:shadow-council}议会{/link}。大地之环的萨满并不命令元素。他们请求，他们协商，他们铭记元素之灵并非仆从。]=],
		},
		{
			title = "历史",
			text = [=[• {b}新萨满。{/b}当{link:thrall}萨尔{/link}将{link:orcs}兽人{/link}带回萨满之道时，{link:tauren}牛头人{/link}和兽人的道路交汇了。{link:third-war}第三次战争{/link}之后，大地之环开始接纳兽人和{link:trolls}巨魔{/link}萨满加入其行列。
• {b}被遗忘者。{/b}当{link:forsaken}被遗忘者{/link}请求加入{link:horde}部落{/link}时，他们声称要在大地的治愈之力中寻找解除亡灵状态的方法。萨尔和{link:cairne-bloodhoof}凯恩·血蹄{/link}心存戒备。正是大地之环的长老{link:shadow-council}议会{/link}敦促部落帮助他们。]=],
		},
		{
			title = "当今",
			text = [=[大地之环的萨满守望着{link:kalimdor}卡利姆多{/link}及更远地方的{link:elements}元素{/link}。他们为所听到的东西而忧虑。火焰在{link:blackrock-mountain}黑石{/link}的深处肆虐，许多土地上的元素都日益躁动。睿智的{link:tauren}牛头人{/link}{link:muln-earthfury}穆恩·地怒{/link}领导着大地之环，尽管他很少露面。]=],
		},
	},
})

Translate("zhCN", "twilight-s-hammer", {
	title = "暮光之锤",
	sections = {
		{
			title = "概述",
			text = [=[暮光之锤是一个末日教派。它曾是{link:horde}部落{/link}中的一个{link:orcs}兽人{/link}氏族。如今，它是一个由各种族狂人组成的团体，他们崇拜埋藏在世界之下的古老力量，渴望万物的终结。教派聚集之处，黑暗中便举行着诡异的仪式。]=],
		},
		{
			title = "起源",
			text = [=[暮光之锤原是{link:horde}部落{/link}的一个氏族，由双头{link:ogres}食人魔{/link}法师古加尔领导，他是{link:gul-dan}古尔丹{/link}最亲近的仆从之一。即使在{link:orcs}兽人{/link}之中，其成员也被视为令人畏惧的狂热者。他们相信世界注定毁灭，而他们的任务就是加速它的终结。]=],
		},
		{
			title = "历史",
			text = [=[• {b}第二次战争。{/b}在{link:second-war}第二次战争{/link}期间，{link:gul-dan}古尔丹{/link}背叛了{link:horde}部落{/link}，去寻找{link:sargeras}萨格拉斯{/link}之墓。古加尔和他的氏族追随了他。大酋长{link:orgrim-doomhammer}奥格瑞姆·毁灭之锤{/link}调转大军讨伐叛徒，击溃了这个氏族，而{link:alliance}联盟{/link}则趁乱占了上风。这个时代的编年史没有记载古加尔的下场。
• {b}教派重生。{/b}这个氏族并没有消亡。它成为一个崇拜上古之神的教派，上古之神是被囚禁在{link:azeroth}艾泽拉斯{/link}深处的黑暗力量。它开始吸引各个种族中同样渴望毁灭的成员。]=],
		},
		{
			title = "当今",
			text = [=[教派在隐秘之处活动。有人在{link:ashenvale}灰谷{/link}{link:blackfathom-deeps}黑暗深渊{/link}被淹没的废墟中发现了它的成员，他们在{link:naga}纳迦{/link}之中举行黑暗仪式。据说它的营地位于遥远南方的{link:silithus}希利苏斯{/link}沙漠中。没有人知道有多少人为暮光之锤效力，也不知道其成员离世间的王座有多近。]=],
		},
	},
})

Translate("zhCN", "burning-blade", {
	title = "火刃氏族",
	sections = {
		{
			title = "概述",
			text = [=[火刃氏族曾是一个以可怕剑士著称的{link:orcs}兽人{/link}氏族。如今，它主要是一个藏身于新{link:horde}部落{/link}兽人之中的恶魔崇拜教派。其成员为{link:burning-legion}燃烧军团{/link}效力，竭力将族人拖回{link:thrall}萨尔{/link}曾将他们解救出来的那种腐化之中。]=],
		},
		{
			title = "起源",
			text = [=[在德拉诺，火刃是一个{link:orcs}兽人{/link}氏族，以其剑圣闻名。当兽人落入恶魔的掌控时，火刃氏族比大多数氏族堕落得更深。在{link:first-war}第一次战争{/link}和{link:second-war}第二次战争{/link}中，它的战士是一个混乱的团体，为战斗而疯狂，不忠于任何人。只有在极度需要之时，他们才会被放出去对付敌人。]=],
		},
		{
			title = "历史",
			text = [=[• {b}两条道路。{/b}{link:second-war}第二次战争{/link}之后，氏族中的一些剑圣加入了{link:thrall}萨尔{/link}的新的{link:horde}部落{/link}，并发誓要摆脱恶魔的控制。另一些人仍然忠于恶魔。在最后的{link:orcs}兽人{/link}术士组织{link:shadow-council}暗影议会{/link}的掌控下，这些人成为了一个秘密教派。
• {b}教派蔓延。{/b}这个教派接纳了其他种族的成员，甚至包括与其同样效忠{link:burning-legion}燃烧军团{/link}的{link:humans}人类{/link}和{link:forsaken}被遗忘者{/link}。]=],
		},
		{
			title = "当今",
			text = [=[火刃氏族在{link:durotar}杜隆塔尔{/link}和{link:the-barrens}贫瘠之地{/link}内部滋生蔓延。它的信徒藏身于杜隆塔尔的{link:skull-rock}骷髅石{/link}和尘风洞穴等洞穴中，并在{link:orgrimmar}奥格瑞玛{/link}地下密谋。在{link:desolace}凄凉之地{/link}，他们占据着{link:thunder-axe-fortress}雷斧堡垒{/link}，他们的恶魔主人在那里自由行走。{link:horde}部落{/link}的战士们不停地追剿他们，但这个教派似乎总能找到新的信徒。]=],
		},
	},
})

Translate("zhCN", "dark-iron-dwarves", {
	title = "黑铁矮人",
	aliases = { "黑铁氏族", "黑铁" },
	sections = {
		{
			title = "概述",
			text = [=[黑铁矮人是三大{link:dwarves}矮人{/link}氏族中最令人畏惧的一支。他们是火焰与黑暗魔法的大师。两个世纪前，他们向自己的同族开战，在战败之际释放了一位火焰领主，并被其奴役。如今他们居住在{link:blackrock-mountain}黑石山{/link}的深处，被束缚于为炎魔之王{link:ragnar-thunderbrew}拉格纳{/link}罗斯效力。]=],
		},
		{
			title = "起源",
			text = [=[很久以前，卡兹莫丹的{link:dwarves}矮人{/link}是一个统一的民族，由至高王莫迪姆斯·安威玛尔在{link:ironforge}铁炉堡{/link}统治。莫迪姆斯死后，三个氏族为争夺王位而战：铜须氏族、蛮锤氏族和术士领主{link:ruins-of-thaurissan}索瑞森{/link}的黑铁氏族。铜须氏族获胜，并将其他氏族驱逐出去。黑铁矮人南迁，在群山之中建起了索瑞森城。]=],
		},
		{
			title = "历史",
			text = [=[• {b}三锤之战。{/b}在{link:dark-portal}黑暗之门{/link}开启前大约两百三十年，黑铁矮人同时进攻了{link:ironforge}铁炉堡{/link}和蛮锤氏族的据点{link:grim-batol}格瑞姆巴托{/link}。他们在铁炉堡城门前被击败。
• {b}{link:ragnar-thunderbrew}拉格纳{/link}罗斯的降临。{/b}绝望之中，{link:ruins-of-thaurissan}索瑞森{/link}寻求一股强大的力量来援助自己。他召唤了火{link:elements}元素{/link}之王拉格纳罗斯。炎魔之王的降临撕裂了大地，形成了{link:searing-gorge}灼热峡谷{/link}和{link:burning-steppes}燃烧平原{/link}。{link:blackrock-mountain}黑石山{/link}在城市原址上拔地而起，黑铁矮人沦为拉格纳罗斯的奴隶。]=],
		},
		{
			title = "当今",
			text = [=[达格兰·{link:ruins-of-thaurissan}索瑞森{/link}皇帝从{link:blackrock-mountain}黑石山{/link}深处的暗炉城统治黑铁矮人。{link:ragnar-thunderbrew}拉格纳{/link}罗斯则从下方的熔火之心统治着他们所有人。黑铁部队袭击{link:searing-gorge}灼热峡谷{/link}，在{link:badlands}废土{/link}挖掘，并威胁着{link:wetlands}湿地{/link}。国王{link:magni-bronzebeard}麦格尼·铜须{/link}坚称他的女儿茉艾拉被皇帝掳走，他要把她夺回来。]=],
		},
	},
})

Translate("zhCN", "steamwheedle-cartel", {
	title = "热砂港",
	aliases = { "热砂" },
	sections = {
		{
			title = "概述",
			text = [=[{link:steamwheedle-port}热砂港{/link}是最大的地精贸易集团。它在大海两岸拥有港口和城镇，并向任何有{link:ginro-hearthkindle}金{/link}币的顾客敞开大门。热砂港只有一种忠诚：利润。它的中立使它富有，它也以雇来的打手守护着这种中立。]=],
		},
		{
			title = "起源",
			text = [=[地精在{link:second-war}第二次战争{/link}中为旧{link:horde}部落{/link}效力。该集团的贸易亲王向{link:orcs}兽人{/link}出售机械、地图、炼{link:ginro-hearthkindle}金{/link}药剂和飞艇，并为毁灭之锤的舰队建造船只。部落战败后，地精们吸取了教训：向双方出售，比投靠任何一方都更有利可图。]=],
		},
		{
			title = "历史",
			text = [=[• {b}{link:booty-bay}藏宝海湾{/link}。{/b}在{link:first-war}第一次战争{/link}之前，{link:steamwheedle-port}热砂港{/link}的地精将{link:trolls}巨魔{/link}从{link:stranglethorn-vale}荆棘谷{/link}南端的一个小港口赶走。他们将其变成了自己的港口藏宝海湾。
• {b}跨越大海。{/b}在随后的岁月里，热砂港在{link:kalimdor}卡利姆多{/link}各地建造或占据了城镇：{link:the-barrens}贫瘠之地{/link}海岸上的{link:ratchet}棘齿城{/link}、{link:tanaris}塔纳利斯{/link}沙漠中的{link:gadgetzan}加基森{/link}，以及{link:winterspring}冬泉谷{/link}冰封北方的{link:everlook}永望镇{/link}。]=],
		},
		{
			title = "当今",
			text = [=[{link:steamwheedle-port}热砂港{/link}的城镇是避风港，{link:orcs}兽人{/link}和{link:humans}人类{/link}可以在那里交易而不必拔刀相向。它的打手以铁腕维持和平。{link:baron-revilgaz}大财主里维加兹{/link}统治{link:booty-bay}藏宝海湾{/link}，{link:gazlowe}加兹鲁维{/link}看守{link:ratchet}棘齿城{/link}，{link:marin-noggenfogger}诺格弗格{/link}市长治理{link:gadgetzan}加基森{/link}。每座城镇都在与海盗、竞争对手和周围的荒野作斗争。它的许多麻烦来自{link:venture-company}风险投资公司{/link}，那是一个毫无它这般规矩的地精财团。]=],
		},
	},
})

Translate("zhCN", "venture-company", {
	title = "风险投资公司",
	sections = {
		{
			title = "概述",
			text = [=[风险投资公司是一个掠夺世界财富的地精财团。只要一样东西可以被开采、砍伐或从地下抽出来，风险投资公司就会把它拿走，毫不在乎谁先住在那里。它的伐木机和钻机所过之处，只留下被污染的湖泊和光秃秃的山丘。]=],
		},
		{
			title = "起源",
			text = [=[没有任何编年史记载风险投资公司的成立。它是安德麦的地精财团之一，多年来一直由其总裁大亨{link:razzle-sprysprocket}拉兹{/link}敦克领导。与{link:steamwheedle-cartel}热砂港{/link}不同，它不经营中立城镇，也不假装讲究信誉。]=],
		},
		{
			title = "历史",
			text = [=[• {b}在卡利姆多。{/b}该公司在{link:third-war}第三次战争{/link}后来到{link:kalimdor}卡利姆多{/link}，开始掠夺这片土地。它在{link:the-barrens}贫瘠之地{/link}的{link:the-sludge-fen}淤泥沼泽{/link}抽取石油。它砍伐{link:stonetalon-mountains}石爪山脉{/link}的森林，并在{link:tauren}牛头人{/link}拒绝授权后，仍挖进了{link:mulgore}莫高雷{/link}的悬崖。
• {b}在{link:eastern-kingdoms}东部王国{/link}。{/b}在{link:stranglethorn-vale}荆棘谷{/link}，该公司为获取木材而清除丛林，并挖掘稀有水晶。它还向{link:defias-brotherhood}迪菲亚兄弟会{/link}出售黑暗的秘密。]=],
		},
		{
			title = "当今",
			text = [=[风险投资公司在世界各地活动。它污染{link:water-wells-of-mulgore}莫高雷的水井{/link}，用巨大的机器撕扯{link:stonetalon-mountains}石爪山脉{/link}的森林。{link:tauren}牛头人{/link}、{link:night-elves}暗夜精灵{/link}和{link:steamwheedle-port}热砂港{/link}的地精都将它视为敌人。它的监工毫不在意，只要矿石源源不断就好。]=],
		},
	},
})

Translate("zhCN", "syndicate", {
	title = "辛迪加",
	sections = {
		{
			title = "概述",
			text = [=[辛迪加是一个由{link:alterac-mountains}奥特兰克{/link}没落贵族组成的犯罪集团。它由盗贼、刺客和强盗组成，为失去王国的领主们效力。其成员在奥特兰克山脉、{link:hillsbrad-foothills}希尔斯布莱德丘陵{/link}和{link:arathi-highlands}阿拉希高地{/link}横行劫掠，梦想着一顶从他们手中被夺走的王冠。]=],
		},
		{
			title = "起源",
			text = [=[在{link:second-war}第二次战争{/link}中，{link:alterac-mountains}奥特兰克{/link}国王艾登·佩里诺德领主将{link:alliance}洛丹伦联盟{/link}出卖给了{link:horde}部落{/link}。战争结束后，奥特兰克被剥夺了王冠和领土。奥特兰克的贵族们从未原谅其他王国。在佩里诺德的继承人阿莱登·佩里诺德领主的带领下，他们召集盗贼和雇佣兵，将其组建为辛迪加。]=],
		},
		{
			title = "历史",
			text = [=[• {b}{link:third-war}第三次战争{/link}之前。{/b}在瘟疫袭击{link:lordaeron}洛丹伦{/link}之前，辛迪加的强盗就已在{link:alterac-mountains}奥特兰克{/link}的{link:moonglade}林地{/link}中活动。
• {b}陷落之后。{/b}洛丹伦陷落后，辛迪加蔓延到它留下的废墟之中。它占领了{link:hillsbrad-foothills}希尔斯布莱德{/link}的{link:durnholde-keep}敦霍尔德城堡{/link}，以及{link:arathi-highlands}阿拉希高地{/link}{link:stromgarde-keep}激流堡{/link}的大部分地区。]=],
		},
		{
			title = "当今",
			text = [=[阿莱登·佩里诺德从{link:alterac-mountains}奥特兰克山脉{/link}的{link:dandred-s-fold}达伦德农场{/link}指挥辛迪加，并将{link:strahnbrad}斯坦恩布莱德{/link}镇占作要塞。{link:lord-falconcrest}法库雷斯特公爵{/link}在{link:stromgarde-keep}激流堡{/link}的废墟中指挥其部队。它从{link:southshore}南海镇{/link}偷窃马匹和货物，并伏击激流堡的士兵。{link:ravenholdt-manor}拉文霍德{/link}的潜行者与它进行着一场漫长的战争，{link:forsaken}被遗忘者{/link}也悬赏捉拿它的每一名成员。]=],
		},
	},
})

Translate("zhCN", "royal-apothecary-society", {
	title = "皇家药剂师协会",
	sections = {
		{
			title = "概述",
			text = [=[皇家药剂师协会是为{link:forsaken}被遗忘者{/link}的女妖之王{link:sylvanas-windrunner}希尔瓦娜斯·风行者{/link}效力的炼{link:ginro-hearthkindle}金{/link}术士组织。在{link:undercity}幽暗城{/link}下的地窖中，它的药剂师们调制毒药和瘟疫。他们宣称的目的是治愈亡灵状态。他们真正的目的则更加黑暗。]=],
		},
		{
			title = "起源",
			text = [=[协会由{link:sylvanas-windrunner}希尔瓦娜斯{/link}在{link:forsaken}被遗忘者{/link}从{link:scourge}天灾军团{/link}手中赢得自由后创立。它的药剂师们着手去做任何活着的炼{link:ginro-hearthkindle}金{/link}术士都不敢做的事：将造就了被遗忘者的瘟疫变成他们自己的武器。药剂师们在{link:undercity}幽暗城{/link}{link:royal-quarter}皇家区{/link}下方的{link:the-apothecarium}炼金房{/link}中设立了实验室。]=],
		},
		{
			title = "历史",
			text = [=[• {b}解药与瘟疫。{/b}当{link:forsaken}被遗忘者{/link}加入{link:horde}部落{/link}时，部落的其他民族相信药剂师们在寻找治愈他们状况的方法。事实上，协会的首要工作是一种新的瘟疫，用来消灭{link:scourge}天灾军团{/link}。
• {b}其他技艺。{/b}协会还复活了死去的马匹，作为被遗忘者的坐骑，并派遣成员四处搜集新的原料。]=],
		},
		{
			title = "当今",
			text = [=[在{link:the-apothecarium}炼金房{/link}中，{link:master-apothecary-faranell}大药剂师法拉尼尔{/link}监督着新瘟疫的研制，协会的特工在{link:hillsbrad-foothills}希尔斯布莱德{/link}的田野和其他地方对其进行测试。它的药剂师在每一个{link:forsaken}被遗忘者{/link}前哨中效力。他们在{link:horde}部落{/link}中的盟友越来越不安地注视着他们。]=],
		},
	},
})

Translate("zhCN", "darkspear-trolls", {
	title = "暗矛巨魔",
	aliases = { "暗矛部族", "暗矛" },
	sections = {
		{
			title = "概述",
			text = [=[暗矛是一个与{link:horde}部落{/link}站在一起的丛林{link:trolls}巨魔{/link}部族。在{link:thrall}萨尔{/link}将他们从毁灭中拯救出来之前，他们是被放逐的流浪者。如今，他们是{link:orcs}兽人{/link}最忠诚的盟友。他们是猎手、巫医和凶猛的战士，他们的存续归功于大酋长。]=],
		},
		{
			title = "起源",
			text = [=[暗矛曾是古拉巴什的一个部族，古拉巴什是{link:stranglethorn-vale}荆棘谷{/link}的丛林{link:trolls}巨魔{/link}。当古拉巴什帝国瓦解时，它的各个部族自相残杀，暗矛被驱逐了出去。他们在南方海域的岛屿上建立了新家园。]=],
		},
		{
			title = "历史",
			text = [=[• {b}救援。{/b}当{link:thrall}萨尔{/link}的舰队被风暴冲上他们的岛屿时，暗矛正处于极大的危险之中。来自{link:kul-tiras}库尔提拉斯{/link}的{link:humans}人类{/link}和海中的{link:murlocs}鱼人{/link}正在攻击他们。萨尔与他们并肩作战，而他们的首领森{link:ginro-hearthkindle}金{/link}被掳走。森金死于鱼人之手，但他早已预见到萨尔将带领他的族人前往新的家园。
• {b}卡利姆多。{/b}暗矛随{link:horde}部落{/link}航行到{link:kalimdor}卡利姆多{/link}，定居在{link:durotar}杜隆塔尔{/link}海岸外的{link:echo-isles}回音群岛{/link}。
• {b}扎拉赞。{/b}一名叫扎拉赞的巫医背叛了他的部族。他用黑暗的巫毒术奴役了回音群岛上的许多{link:trolls}巨魔{/link}，并将其余的人赶出了家园。]=],
		},
		{
			title = "当今",
			text = [=[自由的暗矛已定居在{link:durotar}杜隆塔尔{/link}海岸，住在他们以森{link:ginro-hearthkindle}金{/link}之名命名的村庄里。森金之子{link:vol-jin}沃金{/link}领导着他们，并在{link:orgrimmar}奥格瑞玛{/link}辅佐{link:thrall}萨尔{/link}。扎拉赞仍统治着{link:echo-isles}回音群岛{/link}，暗矛决心将其夺回。]=],
		},
	},
})

Translate("zhCN", "kingdom-of-ironforge", {
	title = "铁炉堡王国",
	sections = {
		{
			title = "概述",
			text = [=[铁炉堡王国是铜须{link:dwarves}矮人{/link}的国度。它的首都开凿于{link:dun-morogh}丹莫罗{/link}一座大山的腹心，它的{link:the-cauldron}熔炉{/link}已燃烧了数千年。这是一个矿工、铁匠、工程师和学者的王国。它也是{link:alliance}联盟{/link}的两大支柱之一。]=],
		},
		{
			title = "起源",
			text = [=[{link:dwarves}矮人{/link}说他们在远古时代由岩石塑造而成。他们最古老的城市是{link:ironforge}铁炉堡{/link}，很长一段时间里，所有矮人都由这里统治。至高王莫迪姆斯·安威玛尔死后，铜须、蛮锤和黑铁三个氏族争夺王位。铜须氏族守住了铁炉堡，将另外两个氏族驱逐出去。在三锤之战中，他们在城门前击败了{link:dark-iron-dwarves}黑铁矮人{/link}。]=],
		},
		{
			title = "历史",
			text = [=[• {b}{link:humans}人类{/link}之友。{/b}很久以前，来自{link:arathor}阿拉索{/link}的探险者抵达卡兹莫丹。{link:dwarves}矮人{/link}和人类成为朋友，互相交流锻造、工程和魔法的知识。
• {b}{link:second-war}第二次战争{/link}。{/b}当{link:horde}部落{/link}席卷卡兹莫丹时，{link:ironforge}铁炉堡{/link}本身坚守住了。矮人加入了{link:alliance}洛丹伦联盟{/link}，他们不会忘记谁曾与他们并肩而立。
• {b}{link:third-war}第三次战争{/link}。{/b}国王{link:magni-bronzebeard}麦格尼·铜须{/link}的弟弟{link:muradin-bronzebeard}穆拉丁·铜须{/link}随王子{link:arthas-menethil}阿尔萨斯·米奈希尔{/link}前往诺森德，再也没有回来。矮人们为他的失踪而哀悼。
• {b}诺莫瑞根的陷落。{/b}当{link:gnomeregan}诺莫瑞根{/link}失陷时，麦格尼在自己的城市中为幸存的{link:gnomes}侏儒{/link}提供了家园。]=],
		},
		{
			title = "当今",
			text = [=[{link:magni-bronzebeard}国王麦格尼{/link}统治着{link:ironforge}铁炉堡{/link}。他的弟弟{link:brann-bronzebeard}布莱恩·铜须{/link}为{link:explorers-league}探险者协会{/link}游历世界。{link:gelbin-mekkatorque}格尔宾·梅卡托克{/link}的{link:gnomes}侏儒{/link}住在城市中心的{link:tinker-town}侏儒区{/link}。{link:dwarves}矮人{/link}士兵守卫着{link:loch-modan}洛克莫丹{/link}和南方的关隘。{link:dark-iron-dwarves}黑铁矮人{/link}从{link:blackrock-mountain}黑石山{/link}发出威胁，麦格尼为他的女儿茉艾拉而悲伤，他说她被他们的皇帝掳走了。]=],
		},
	},
})
